"use client"

import * as React from "react"
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group"
import { Radio as RadioPrimitive } from "@base-ui/react/radio"

import { cn } from "@/lib/utils"

// Ledger Light Radio — checked ring becomes the primary blue chip (same rim +
// soft glow as the Button) with a white centered dot.

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const RadioGroup = React.forwardRef<
  React.ElementRef<typeof RadioGroupPrimitive>,
  WithClassName<RadioGroupPrimitive.Props>
>(({ className, ...props }, ref) => (
  <RadioGroupPrimitive
    data-slot="radio-group"
    className={cn("grid gap-2", className)}
    {...props}
    ref={ref}
  />
))
RadioGroup.displayName = "RadioGroup"

const RadioGroupItem = React.forwardRef<
  React.ElementRef<typeof RadioPrimitive.Root>,
  WithClassName<RadioPrimitive.Root.Props>
>(({ className, ...props }, ref) => (
  <RadioPrimitive.Root
    data-slot="radio-group-item"
    ref={ref}
    className={cn(
      "inline-flex items-center justify-center aspect-square h-4 w-4 rounded-full",
      "border border-border bg-input text-primary",
      "transition-all duration-fast ease-out",
      "hover:border-ring/45",
      "focus-visible:outline-none focus-visible:ring-[0.1875rem] focus-visible:ring-ring/30",
      "data-disabled:cursor-not-allowed data-disabled:opacity-50",
      "data-checked:border-[var(--primary-rim)] data-checked:bg-primary",
      "data-checked:shadow-[var(--shadow-primary-control)]",
      className
    )}
    {...props}
  >
    <RadioPrimitive.Indicator data-slot="radio-group-indicator" className="size-full flex items-center justify-center">
      <div className="h-1.5 w-1.5 rounded-full bg-primary-foreground" />
    </RadioPrimitive.Indicator>
  </RadioPrimitive.Root>
))
RadioGroupItem.displayName = "RadioGroupItem"

export { RadioGroup, RadioGroupItem }
